<body>

<div class="status-panel" id="status-panel">
    <div class="panel-header" onclick="togglePanel()">
        <h2>角色状态总览</h2>
        <span class="toggle-btn" id="panel-toggle-btn">▲</span>
    </div>
    <div class="panel-body" id="panel-body">
    </div>
</div>

<script>
    function togglePanel() {
        const panelBody = document.getElementById('panel-body');
        const toggleBtn = document.getElementById('panel-toggle-btn');
        const isCollapsed = panelBody.classList.toggle('collapsed');
        toggleBtn.textContent = isCollapsed ? '▼' : '▲';
    }

    function toggleCard(headerElement) {
        const content = headerElement.nextElementSibling;
        const arrow = headerElement.querySelector('.toggle-arrow');
        content.classList.toggle('collapsed');
        arrow.textContent = content.classList.contains('collapsed') ? '▼' : '▲';
    }

    async function initDisplay() {
        const panelBody = document.getElementById('panel-body');
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data || !messages[0].data.stat_data) {
                panelBody.innerHTML = `<p style="color:var(--danger-color); padding:10px;">无法加载状态数据。</p>`;
                return;
            }

            const data = messages[0].data.stat_data;
            const roles = data['角色'] || [];
            const affections = data['好感度'] || [];
            const trusts = data['信赖度'] || [];
            const thoughts = data['内心想法'] || [];
            const locations = data['当前位置'] || [];

            let allCardsHTML = '';

            for (let i = 0; i < roles.length; i++) {
                const role = roles[i];
                if (!role) continue;

                const affection = affections[i] !== undefined ? affections[i] : 0;
                const trust = trusts[i] !== undefined ? trusts[i] : 0;
                const thought = thoughts[i] || '无';
                const location = locations[i] || '未知';

                const affectionPercentage = Math.max(0, Math.min(100, ((affection + 100) / 200) * 100));
                const trustPercentage = Math.max(0, Math.min(100, trust));

                allCardsHTML += `
                    <div class="character-card">
                        <div class="card-header" onclick="toggleCard(this)">
                            <span class="character-name">${role}</span>
                            <span class="toggle-arrow">▲</span>
                        </div>
                        <div class="card-content">
                            <div class="property">
                                <span class="prop-name">好感度</span>
                                <div class="prop-value">
                                  <span class="prop-value-value">${affection}</span>
                                </div>
                                <div class="progress-bar-container">
                                    <div class="progress-bar-value" style="width: ${affectionPercentage}%; background-color: var(--accent-color);"></div>
                                </div>
                            </div>
                            <div class="property">
                                <span class="prop-name">信赖度</span>
                                <div class="prop-value">
                                  <span class="prop-value-value">${trust}</span>
                                </div>
                                <div class="progress-bar-container">
                                    <div class="progress-bar-value" style="width: ${trustPercentage}%; background-color: var(--accent-trust-color);"></div>
                                </div>
                            </div>
                            <div class="property">
                                <span class="prop-name">内心想法</span>
                                <p class="prop-value">${thought}</p>
                            </div>
                            <div class="property">
                                <span class="prop-name">当前位置</span>
                                <p class="prop-value">${location}</p>
                            </div>
                        </div>
                    </div>
                `;
            }

            panelBody.innerHTML = allCardsHTML || `<p style="color:var(--text-secondary-color); padding:10px;">暂无角色数据。</p>`;

        } catch (error) {
            panelBody.innerHTML = `<p style="color:var(--danger-color); padding:10px;">状态栏加载出错: ${error.message}</p>`;
            console.error(error);
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        initDisplay();
    });

</script>
</body>
</html>
